import 'dart:convert';
import 'dart:developer' as developer;
import 'dart:isolate';
import 'dart:ui';

import 'package:logger/logger.dart';

typedef LoggerIsolateMessage = (LogEvent, bool);
typedef LoggerMessageSender = void Function(Object?);
typedef LoggerMessageSenderLookup = LoggerMessageSender? Function();
typedef LoggerFallback =
    void Function(LogEvent event, Object error, StackTrace stackTrace);

final class LoggerDispatcher {
  LoggerDispatcher({
    required LoggerMessageSenderLookup lookupSender,
    LoggerFallback fallback = developerLoggerFallback,
  }) : _lookupSender = lookupSender,
       _fallback = fallback;

  final LoggerMessageSenderLookup _lookupSender;
  final LoggerFallback _fallback;

  bool log(
    Level level,
    dynamic message, {
    DateTime? time,
    Object? error,
    StackTrace? stackTrace,
    bool toFile = true,
  }) {
    final event = LogEvent(
      level,
      _stringifyMessage(message),
      time: time,
      error: error,
      stackTrace: stackTrace,
    );

    try {
      final sender = _lookupSender();
      if (sender == null) {
        throw StateError("Logger isolate is unavailable");
      }
      sender((event, toFile));
      return true;
    } catch (dispatchError, dispatchStackTrace) {
      try {
        _fallback(event, dispatchError, dispatchStackTrace);
      } catch (_) {
        // Logging must never break its caller.
      }
      return false;
    }
  }
}

final class LoggerPortRegistry {
  LoggerPortRegistry({
    required SendPort? Function() lookupPort,
    required bool Function(SendPort) registerPort,
    required bool Function() removePort,
  }) : _lookupPort = lookupPort,
       _registerPort = registerPort,
       _removePort = removePort;

  factory LoggerPortRegistry.named(String name) => LoggerPortRegistry(
    lookupPort: () => IsolateNameServer.lookupPortByName(name),
    registerPort: (port) => IsolateNameServer.registerPortWithName(port, name),
    removePort: () => IsolateNameServer.removePortNameMapping(name),
  );

  final SendPort? Function() _lookupPort;
  final bool Function(SendPort) _registerPort;
  final bool Function() _removePort;

  SendPort? lookup() => _lookupPort();

  bool register(SendPort port) => _registerPort(port);

  bool removeIfCurrent(SendPort port) {
    if (_lookupPort() != port) {
      return false;
    }
    return _removePort();
  }
}

void developerLoggerFallback(
  LogEvent event,
  Object dispatchError,
  StackTrace dispatchStackTrace,
) {
  try {
    final originalError = event.error == null
        ? ""
        : "\nOriginal error: ${_safeToString(event.error)}";
    developer.log(
      _safeToString(event.message),
      name: "StackWallet.Logging",
      level: event.level.value ~/ 5,
      time: event.time,
      error:
          "Logger dispatch failed: ${_safeToString(dispatchError)}"
          "$originalError",
      stackTrace: event.stackTrace ?? dispatchStackTrace,
    );
  } catch (_) {
    // The emergency path must remain independent of application logging.
  }
}

String _stringifyMessage(dynamic message) {
  try {
    return !(message is Map || message is Iterable)
        ? message.toString()
        : JsonEncoder.withIndent(
            '  ',
            (object) => object.toString(),
          ).convert(message);
  } catch (error) {
    return "<could not stringify ${message.runtimeType}: "
        "${_safeToString(error)}>";
  }
}

String _safeToString(Object? value) {
  try {
    return value.toString();
  } catch (_) {
    return "<unprintable ${value.runtimeType}>";
  }
}
